  TypeInference(AbstractCompiler compiler, ControlFlowGraph<Node> cfg,
                ReverseAbstractInterpreter reverseInterpreter,
                Scope functionScope) {
    this(compiler, cfg, reverseInterpreter, functionScope,
         ImmutableSet.<Var>of());
